//! `sensor/*` commands (`components/sensor/websocket_api.py`), from HA
//! 2026.6.1's tables (`sensor_units.json`, generated by running HA's own
//! code: `_NUMERIC_DEVICE_CLASSES`, and `DEVICE_CLASS_UNITS` for the
//! classes with a unit converter, each sorted with `str.casefold`).

use super::{Conn, Invalid};
use serde_json::{Map, Value, json};

const TABLES: &str = include_str!("../sensor_units.json");

fn tables() -> Value {
    serde_json::from_str(TABLES).unwrap_or_default()
}

/// The command's schema as voluptuous applies it: every extra key and
/// bad value (in key order), then missing required keys, one per line.
fn validate(msg: &Map<String, Value>, device_class: bool) -> Result<(), Invalid> {
    let mut errors = Vec::new();
    for (k, v) in msg {
        match k.as_str() {
            "id" | "type" => {}
            "device_class" if device_class => {
                if !v.is_string() {
                    errors.push(
                        "expected str for dictionary value @ data['device_class']".to_owned(),
                    );
                }
            }
            k => errors.push(format!("extra keys not allowed @ data['{k}']")),
        }
    }
    if device_class && !msg.contains_key("device_class") {
        errors.push("required key not provided @ data['device_class']".to_owned());
    }
    match errors.is_empty() {
        true => Ok(()),
        false => Err(errors.join("\n")),
    }
}

pub(super) fn dispatch(
    conn: &mut Conn,
    id: u64,
    ty: &str,
    msg: &Map<String, Value>,
) -> Option<Result<(), Invalid>> {
    Some(match ty {
        // HA's list is in Python set order (it varies); hars sorts it.
        "sensor/numeric_device_classes" => validate(msg, false).map(|()| {
            conn.out
                .result(id, json!({"numeric_device_classes": tables()["numeric"]}));
        }),
        "sensor/device_class_convertible_units" => validate(msg, true).map(|()| {
            let dc = msg["device_class"].as_str().unwrap_or_default();
            let units = tables()["units"].get(dc).cloned().unwrap_or(json!([]));
            conn.out.result(id, json!({ "units": units }));
        }),
        _ => return None,
    })
}
